class Solution {
    public int minStoneSum(int[] piles,int k){
        PriorityQueue<Integer> heap=new PriorityQueue<>(Collections.reverseOrder());
        for(int pile:piles)heap.offer(pile);
        while(k-->0){
            int value=heap.poll();
            heap.offer(value-value/2);
        }
        int answer=0;
        for(int value:heap)answer+=value;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minStoneSum(piles:IntArray,kValue:Int):Int{
        val heap=java.util.PriorityQueue<Int>(compareByDescending{
            it
        });
        for(pile in piles)heap.add(pile);
        repeat(kValue){
            val value=heap.remove();
            heap.add(value-value/2)
        };
        return heap.sum()
    }
}

code.cpp:
class Solution {
    public: int minStoneSum(vector<int>& piles,int k){
        priority_queue<int> heap(piles.begin(),piles.end());
        while(k--){
            int value=heap.top();
            heap.pop();
            heap.push(value-value/2);
        }
        int answer=0;
        while(!heap.empty()){
            answer+=heap.top();
            heap.pop();
        }
        return answer;
    }
};
